package com.villaserena.api.experiencias;

import static com.villaserena.api.experiencias.ExperienciasDto.*;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.villaserena.api.auth.UsuarioActual;
import com.villaserena.api.comun.*;
import com.villaserena.api.config.PropiedadesVillaSerena;
import com.villaserena.api.reservas.*;

@Service
@Transactional(readOnly=true)
public class ExperienciasService {
 private final JdbcTemplate db; private final Clock clock; private final String photos;
 private final CargoService charges; private final CuentaService accounts;
 private static final ZoneId ZONE=ZoneId.of("America/Guatemala");
 public ExperienciasService(JdbcTemplate db,Clock clock,PropiedadesVillaSerena config,CargoService charges,CuentaService accounts){this.db=db;this.clock=clock;this.photos=config.archivos().urlPublica();this.charges=charges;this.accounts=accounts;}
 private ApiException conflict(String message){return ApiException.conflicto("EXPERIENCIA_CONFLICTO",message);}
 private Map<String,Object> one(String sql,Object...args){var rows=db.queryForList(sql,args);if(rows.isEmpty())throw ApiException.noEncontrado();return rows.getFirst();}
 private long number(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}
 private Instant time(Map<String,Object> r,String key){return ((Timestamp)r.get(key)).toInstant();}
 private void revision(Map<String,Object> row,long version){if(number(row,"version")!=version)throw conflict("La información cambió. Actualice antes de continuar.");}
 // Todas las mutaciones de una experiencia toman primero este bloqueo, también al modificar sus horarios.
 private Map<String,Object> lock(long id){return one("SELECT * FROM experiences WHERE id=? FOR UPDATE",id);}
 private Map<String,Object> stay(String code,boolean create,boolean write,boolean owned){
  var r=one("SELECT * FROM reservations WHERE code=?"+(owned?" AND guest_id=?":"")+(write?" FOR UPDATE":""),owned?new Object[]{code,UsuarioActual.id()}:new Object[]{code});
  if(create&&(!Set.of("CONFIRMADA","EN_ESTADIA").contains(r.get("status"))||((java.sql.Date)r.get("checkout_date")).toLocalDate().isBefore(LocalDate.now(clock.withZone(ZONE)))))throw conflict("Su reserva de alojamiento debe estar confirmada y vigente.");
  return r;
 }
 private String photo(Object key){return key==null||photos==null||photos.isBlank()?null:photos.replaceAll("/+$","")+"/"+key.toString().replaceAll("^/+","");}
 private Map<String,Object> offer(long id){var r=one("SELECT e.*,a.name,a.description,a.photo_key,a.status AS amenity_status FROM experiences e JOIN hotel_amenities a ON a.id=e.amenity_id WHERE e.id=?",id);var out=new LinkedHashMap<String,Object>();
  out.put("id",id);out.put("amenidadId",r.get("amenity_id"));out.put("nombre",r.get("name"));out.put("descripcion",r.get("description"));out.put("categoria",r.get("category"));if(photo(r.get("photo_key"))!=null)out.put("fotoUrl",photo(r.get("photo_key")));
  out.put("activa",Boolean.TRUE.equals(r.get("active"))&&"ACTIVO".equals(r.get("amenity_status")));out.put("modalidad",r.get("mode"));out.put("tarifa",r.get("pricing"));out.put("precio",r.get("price"));out.put("cobro",r.get("payment"));out.put("duracionMinutos",r.get("duration_minutes"));out.put("requiereEstadia",r.get("requires_stay"));out.put("cancelable",r.get("cancellable"));out.put("antelacionCancelacionMinutos",r.get("cancel_notice_minutes"));out.put("version",r.get("version"));return out;
 }
 public List<Map<String,Object>> catalog(String code){if(code!=null)stay(code,true,false,true);return db.queryForList("SELECT id FROM experiences ORDER BY id",Long.class).stream().map(this::offer).filter(r->code==null||Boolean.TRUE.equals(r.get("activa"))).toList();}
 @Transactional public Map<String,Object> configure(Long id,Config p){
  boolean free="GRATUITA".equals(p.tarifa());if(free?(p.precio().signum()!=0||!"SIN_CARGO".equals(p.cobro())):(p.precio().signum()<=0||"SIN_CARGO".equals(p.cobro())))throw conflict("Configure un precio y una forma de cobro compatibles.");
  one("SELECT id FROM hotel_amenities WHERE id=? FOR UPDATE",p.amenidadId());
  if(id==null){if(!db.queryForList("SELECT id FROM experiences WHERE amenity_id=?",Long.class,p.amenidadId()).isEmpty())throw conflict("La amenidad ya tiene una experiencia configurada.");id=db.queryForObject("INSERT INTO experiences(amenity_id,category,active,mode,pricing,price,payment,duration_minutes,requires_stay,cancellable,cancel_notice_minutes) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,p.amenidadId(),p.categoria().trim(),p.activa(),p.modalidad(),p.tarifa(),p.precio(),p.cobro(),p.duracionMinutos(),p.requiereEstadia(),p.cancelable(),p.antelacionCancelacionMinutos());}
  else{var old=lock(id);revision(old,p.version());if(number(old,"amenity_id")!=p.amenidadId())throw conflict("No se puede cambiar la amenidad vinculada.");db.update("UPDATE experiences SET category=?,active=?,mode=?,pricing=?,price=?,payment=?,duration_minutes=?,requires_stay=?,cancellable=?,cancel_notice_minutes=?,version=version+1 WHERE id=?",p.categoria().trim(),p.activa(),p.modalidad(),p.tarifa(),p.precio(),p.cobro(),p.duracionMinutos(),p.requiereEstadia(),p.cancelable(),p.antelacionCancelacionMinutos(),id);}
  return offer(id);
 }
 private int used(long slot){return db.queryForObject("SELECT coalesce(sum(people),0) FROM experience_bookings WHERE slot_id=? AND status IN ('PENDIENTE','CONFIRMADA')",Integer.class,slot);}
 private Map<String,Object> slot(long id){var r=one("SELECT * FROM experience_slots WHERE id=?",id);return Map.of("id",id,"experienciaId",r.get("experience_id"),"inicio",time(r,"starts_at"),"fin",time(r,"ends_at"),"capacidad",r.get("capacity"),"disponibles",Math.max(0,((Number)r.get("capacity")).intValue()-used(id)),"activo",r.get("active"),"version",r.get("version"));}
 public List<Map<String,Object>> slots(long experience,String code,LocalDate date){Map<String,Object> r=code==null?null:stay(code,true,false,true);var e=offer(experience);if(code!=null&&!Boolean.TRUE.equals(e.get("activa")))throw ApiException.noEncontrado();
  return db.queryForList("SELECT id FROM experience_slots WHERE experience_id=? ORDER BY starts_at",Long.class,experience).stream().map(this::slot).filter(s->date==null||((Instant)s.get("inicio")).atZone(ZONE).toLocalDate().equals(date)).filter(s->code==null||Boolean.TRUE.equals(s.get("activo"))&&((Instant)s.get("inicio")).isAfter(clock.instant())&&withinStay(r,(Instant)s.get("inicio"))&&withinStay(r,((Instant)s.get("fin")).minusNanos(1))).toList();
 }
 private boolean withinStay(Map<String,Object> stay,Instant instant){var date=instant.atZone(ZONE).toLocalDate();return !date.isBefore(((java.sql.Date)stay.get("checkin_date")).toLocalDate())&&!date.isAfter(((java.sql.Date)stay.get("checkout_date")).toLocalDate());}
 @Transactional public Map<String,Object> schedule(long experience,Long id,Slot p){var e=lock(experience);Instant end=p.inicio().plusSeconds(number(e,"duration_minutes")*60);if(!p.inicio().isAfter(clock.instant()))throw conflict("El horario debe comenzar en una fecha futura.");
  if(id!=null){var old=one("SELECT * FROM experience_slots WHERE id=? AND experience_id=? FOR UPDATE",id,experience);revision(old,p.version());if(!p.inicio().equals(time(old,"starts_at"))&&db.queryForObject("SELECT count(*) FROM experience_bookings WHERE slot_id=?",Integer.class,id)>0)throw conflict("No se puede mover un horario con reservas registradas.");if(p.capacidad()<used(id))throw conflict("La capacidad no puede ser menor que los cupos reservados.");if(p.inicio().equals(time(old,"starts_at")))end=time(old,"ends_at");}
  if(p.activo()&&db.queryForObject("SELECT count(*) FROM experience_slots WHERE experience_id=? AND active AND id<>? AND starts_at<? AND ends_at>?",Integer.class,experience,id==null?-1:id,Timestamp.from(end),Timestamp.from(p.inicio()))>0)throw conflict("El horario se superpone con otro horario activo de la experiencia.");
  if(id==null){if(!db.queryForList("SELECT id FROM experience_slots WHERE experience_id=? AND starts_at=?",Long.class,experience,Timestamp.from(p.inicio())).isEmpty())throw conflict("El horario ya existe.");id=db.queryForObject("INSERT INTO experience_slots(experience_id,starts_at,ends_at,capacity,active) VALUES(?,?,?,?,?) RETURNING id",Long.class,experience,Timestamp.from(p.inicio()),Timestamp.from(end),p.capacidad(),p.activo());}else db.update("UPDATE experience_slots SET starts_at=?,ends_at=?,capacity=?,active=?,version=version+1 WHERE id=?",Timestamp.from(p.inicio()),Timestamp.from(end),p.capacidad(),p.activo(),id);return slot(id);
 }
 private void eligible(Map<String,Object> e,Map<String,Object> r,Map<String,Object> s){if(!Boolean.TRUE.equals(offer(number(e,"id")).get("activa"))||!Boolean.TRUE.equals(s.get("active"))||!time(s,"starts_at").isAfter(clock.instant())||!withinStay(r,time(s,"starts_at"))||!withinStay(r,time(s,"ends_at").minusNanos(1)))throw conflict("La experiencia o el horario no están disponibles para su estancia.");
  if("COORDINACION".equals(e.get("mode"))||"ANTICIPADO".equals(e.get("payment")))throw conflict("Esta experiencia requiere coordinación. Envíe una consulta a Recepción.");
  if((Boolean.TRUE.equals(e.get("requires_stay"))||"CUENTA".equals(e.get("payment")))&&!"EN_ESTADIA".equals(r.get("status")))throw conflict("Esta experiencia requiere una estadía iniciada.");
 }
 @Transactional public Map<String,Object> book(String code,Booking p){var preliminary=one("SELECT experience_id FROM experience_slots WHERE id=?",p.horarioId());var e=lock(number(preliminary,"experience_id"));var r=stay(code,true,true,true);long rid=number(r,"id");
  var prior=db.queryForList("SELECT * FROM experience_bookings WHERE reservation_id=? AND request_key=?",rid,p.clave());if(!prior.isEmpty()){var b=prior.getFirst();if(number(b,"slot_id")!=p.horarioId()||number(b,"people")!=p.personas())throw conflict("El identificador ya corresponde a otra solicitud.");return booking(number(b,"id"),false);}
  var s=one("SELECT * FROM experience_slots WHERE id=? FOR UPDATE",p.horarioId());eligible(e,r,s);if(used(p.horarioId())+p.personas()>number(s,"capacity"))throw conflict("No hay cupos suficientes para ese horario.");
  if(db.queryForObject("SELECT count(*) FROM experience_bookings WHERE reservation_id=? AND slot_id=? AND status IN ('PENDIENTE','CONFIRMADA')",Integer.class,rid,p.horarioId())>0)throw conflict("Usted ya tiene una reserva activa en ese horario.");
  BigDecimal total=((BigDecimal)e.get("price")).multiply(BigDecimal.valueOf("POR_PERSONA".equals(e.get("pricing"))?p.personas():1));if(total.compareTo(new BigDecimal("9999999999.99"))>0)throw conflict("El importe excede el límite permitido.");
  String state="INMEDIATA".equals(e.get("mode"))?"CONFIRMADA":"PENDIENTE";Long id=db.queryForObject("INSERT INTO experience_bookings(reference,reservation_id,slot_id,request_key,people,experience_name,total,payment,cancellable,cancel_notice_minutes,status) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,"EX-"+UUID.randomUUID().toString().replace("-",""),rid,p.horarioId(),p.clave(),p.personas(),offer(number(e,"id")).get("nombre"),total,e.get("payment"),e.get("cancellable"),e.get("cancel_notice_minutes"),state);
  if("CONFIRMADA".equals(state))charge(id,r);return booking(id,false);
 }
 private void charge(long id,Map<String,Object> r){var b=one("SELECT * FROM experience_bookings WHERE id=?",id);if(!"CUENTA".equals(b.get("payment"))||b.get("charge_id")!=null)return;long account=db.queryForObject("SELECT id FROM accounts WHERE reservation_id=?",Long.class,r.get("id"));
  var cargo=charges.registrarCargo(account,new NuevoCargo(TipoCargo.SERVICIO,CategoriaServicio.OTRO,"Experiencia · "+b.get("reference"),1,(BigDecimal)b.get("total"),null),"HUESPED".equals(UsuarioActual.rol())?Responsable.HUESPED:Responsable.empleado(UsuarioActual.id()));db.update("UPDATE experience_bookings SET charge_id=? WHERE id=?",cargo.getId(),id);
 }
 private boolean canCancel(Map<String,Object> b){return Set.of("PENDIENTE","CONFIRMADA").contains(b.get("status"))&&Boolean.TRUE.equals(b.get("cancellable"))&&clock.instant().isBefore(time(b,"starts_at").minusSeconds(number(b,"cancel_notice_minutes")*60));}
 private Map<String,Object> booking(long id,boolean staff){var b=one("SELECT b.*,r.code AS lodging_code,r.guest_id,h.full_name AS guest_name,rm.number AS room_number,s.experience_id,s.starts_at,s.ends_at,e.category,a.photo_key FROM experience_bookings b JOIN reservations r ON r.id=b.reservation_id JOIN guests h ON h.id=r.guest_id LEFT JOIN rooms rm ON rm.id=r.room_id JOIN experience_slots s ON s.id=b.slot_id JOIN experiences e ON e.id=s.experience_id JOIN hotel_amenities a ON a.id=e.amenity_id WHERE b.id=?",id);
  var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("referencia",b.get("reference"));out.put("codigoReserva",b.get("lodging_code"));out.put("experienciaId",b.get("experience_id"));out.put("nombre",b.get("experience_name"));out.put("categoria",b.get("category"));if(photo(b.get("photo_key"))!=null)out.put("fotoUrl",photo(b.get("photo_key")));out.put("horarioId",b.get("slot_id"));out.put("inicio",time(b,"starts_at"));out.put("fin",time(b,"ends_at"));out.put("personas",b.get("people"));out.put("total",b.get("total"));out.put("moneda","GTQ");out.put("estado",b.get("status"));if(b.get("reason")!=null)out.put("motivo",b.get("reason"));out.put("version",b.get("version"));if(b.get("charge_id")!=null)out.put("cargoId",b.get("charge_id"));out.put("cancelable",canCancel(b));if(staff){out.put("nombreHuesped",b.get("guest_name"));if(b.get("room_number")!=null)out.put("habitacion",b.get("room_number"));}return out;
 }
 public List<Map<String,Object>> bookings(String code,LocalDate date,Long experience,String status){Long rid=code==null?null:number(stay(code,false,false,true),"id");return db.queryForList("SELECT b.id FROM experience_bookings b JOIN experience_slots s ON s.id=b.slot_id WHERE (?::bigint IS NULL OR b.reservation_id=?) AND (?::bigint IS NULL OR s.experience_id=?) AND (?::text IS NULL OR b.status=?) ORDER BY s.starts_at,b.id",Long.class,rid,rid,experience,experience,status,status).stream().map(id->booking(id,code==null)).filter(b->date==null||((Instant)b.get("inicio")).atZone(ZONE).toLocalDate().equals(date)).toList();}
 @Transactional public Map<String,Object> decide(long id,Decision p){var initial=booking(id,true);var e=lock(number(initial,"experienciaId"));var r=stay((String)initial.get("codigoReserva"),"APROBAR".equals(p.accion()),true,false);var b=one("SELECT * FROM experience_bookings WHERE id=? FOR UPDATE",id);String target="APROBAR".equals(p.accion())?"CONFIRMADA":"RECHAZADA";
  if(target.equals(b.get("status")))return booking(id,true);revision(b,p.version());if(!"PENDIENTE".equals(b.get("status")))throw conflict("Solo puede decidir una solicitud pendiente.");
  if("RECHAZADA".equals(target)&&(p.motivo()==null||p.motivo().isBlank()))throw conflict("Indique el motivo del rechazo.");if("CONFIRMADA".equals(target)){var s=one("SELECT * FROM experience_slots WHERE id=? FOR UPDATE",b.get("slot_id"));eligible(e,r,s);charge(id,r);}
  db.update("UPDATE experience_bookings SET status=?,reason=?,decided_by=?,version=version+1 WHERE id=?",target,p.motivo(),UsuarioActual.id(),id);return booking(id,true);
 }
 @Transactional public Map<String,Object> cancel(String code,long id,Cancel p){var r=stay(code,false,false,true);var initial=one("SELECT b.id,s.experience_id FROM experience_bookings b JOIN experience_slots s ON s.id=b.slot_id WHERE b.id=? AND b.reservation_id=?",id,r.get("id"));lock(number(initial,"experience_id"));stay(code,false,true,true);var b=one("SELECT b.*,s.starts_at FROM experience_bookings b JOIN experience_slots s ON s.id=b.slot_id WHERE b.id=? FOR UPDATE OF b",id);
  if("CANCELADA".equals(b.get("status")))return booking(id,false);revision(b,p.version());if(!canCancel(b))throw conflict("La política de esta reserva no permite cancelarla en este momento.");
  if(b.get("charge_id")!=null)accounts.anularCargo(code,number(b,"charge_id"),p.motivo(),null);
  db.update("UPDATE experience_bookings SET status='CANCELADA',reason=?,version=version+1 WHERE id=?",p.motivo().trim(),id);return booking(id,false);
 }
 private Map<String,Object> inquiry(long id,boolean staff){var q=one("SELECT q.*,a.name,r.code,g.full_name FROM experience_inquiries q JOIN experiences e ON e.id=q.experience_id JOIN hotel_amenities a ON a.id=e.amenity_id JOIN reservations r ON r.id=q.reservation_id JOIN guests g ON g.id=r.guest_id WHERE q.id=?",id);var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("experienciaId",q.get("experience_id"));out.put("nombre",q.get("name"));out.put("codigoReserva",q.get("code"));out.put("comentario",q.get("comment"));if(q.get("response")!=null)out.put("respuesta",q.get("response"));out.put("estado",q.get("response")==null?"ABIERTA":"RESPONDIDA");out.put("creadaEn",time(q,"created_at"));if(staff)out.put("nombreHuesped",q.get("full_name"));return out;}
 public List<Map<String,Object>> inquiries(String code){Long rid=code==null?null:number(stay(code,false,false,true),"id");return db.queryForList("SELECT id FROM experience_inquiries WHERE (?::bigint IS NULL OR reservation_id=?) ORDER BY created_at DESC",Long.class,rid,rid).stream().map(id->inquiry(id,code==null)).toList();}
 @Transactional public Map<String,Object> ask(String code,long experience,Inquiry p){lock(experience);var r=stay(code,true,true,true);if(!Boolean.TRUE.equals(offer(experience).get("activa")))throw ApiException.noEncontrado();var prior=db.queryForList("SELECT * FROM experience_inquiries WHERE reservation_id=? AND request_key=?",r.get("id"),p.clave());if(!prior.isEmpty()){var q=prior.getFirst();if(number(q,"experience_id")!=experience||!q.get("comment").equals(p.comentario().trim()))throw conflict("El identificador ya corresponde a otra consulta.");return inquiry(number(q,"id"),false);}long id=db.queryForObject("INSERT INTO experience_inquiries(experience_id,reservation_id,request_key,comment) VALUES(?,?,?,?) RETURNING id",Long.class,experience,r.get("id"),p.clave(),p.comentario().trim());return inquiry(id,false);}
 @Transactional public Map<String,Object> answer(long id,Answer p){var q=one("SELECT * FROM experience_inquiries WHERE id=? FOR UPDATE",id);if(q.get("response")!=null&&!q.get("response").equals(p.respuesta().trim()))throw conflict("La consulta ya fue respondida. Actualice la lista.");db.update("UPDATE experience_inquiries SET response=?,responded_by=? WHERE id=?",p.respuesta().trim(),UsuarioActual.id(),id);return inquiry(id,true);}
}
